SELECT d.id AS doc_id, d.doc_code, d.title, d.category_id, d.status, d.summary, d.source_type, d.view_count, d.quote_count, d.favorite_count, d.updated_at, c.category_name, v.index_status, v.version_no, u.nickname AS owner_name FROM biz_document d LEFT JOIN biz_category c ON c.id = d.category_id LEFT JOIN biz_doc_version v ON v.id = d.current_version_id LEFT JOIN sys_user u ON u.id = d.owner_id WHERE d.deleted_at IS NULL
AND (d.title LIKE CONCAT('%', #{keyword}, '%') OR d.doc_code LIKE CONCAT('%', #{keyword}, '%'))
AND d.category_id = #{categoryId}
AND d.status = #{status}
ORDER BY d.updated_at DESC LIMIT #{size} OFFSET #{page}

SELECT count(*) FROM biz_document d WHERE d.deleted_at IS NULL

    AND (d.title LIKE CONCAT('%', #{keyword}, '%') OR d.doc_code LIKE CONCAT('%', #{keyword}, '%'))


    AND d.category_id = #{categoryId}


    AND d.status = #{status}
